import type { Page } from "@playwright/test";

// 32x24 1-frame H.264 MP4 (slate #1e293b) so Playwright never hits media.giphy.com.
const TINY_MP4 = Buffer.from(
  "",
  "base64"
);

// 1x1 lossless WebP for .webp assets.
const TINY_WEBP = Buffer.from(
  "UklGRh4AAABXRUJQVlA4TBEAAAAvAAAAAAfQ//73v/+BiOh/AAA=",
  "base64"
);

/** Fulfill Giphy media requests locally so E2E tests are deterministic and offline-safe. */
export async function mockGiphyMedia(page: Page) {
  await page.route("https://*.giphy.com/**", (route) => {
    const url = route.request().url();
    const isWebp = /\.webp(?:$|\?)/i.test(url);
    return route.fulfill({
      status: 200,
      contentType: isWebp ? "image/webp" : "video/mp4",
      headers: { "access-control-allow-origin": "*" },
      body: isWebp ? TINY_WEBP : TINY_MP4,
    });
  });
}

/** Fail Giphy requests to simulate an offline desktop environment and exercise icon fallback. */
export async function abortGiphyMedia(page: Page) {
  await page.route("https://*.giphy.com/**", (route) =>
    route.abort("internetdisconnected")
  );
}
